<template>
  <view class="archive-page orders-page">
    <MiniBackHome :return-url="returnUrl" :return-label="returnLabel" />
    <view class="archive-page-head"><view><text class="archive-kicker">Capacity Orders</text><text class="archive-title">订单与退款</text><text class="archive-subtitle">查看状态和申请退款。</text></view></view>
    <view class="refund-rules" @tap="refundRulesExpanded = !refundRulesExpanded"><view class="refund-rules-head"><text class="refund-rules-title">退款说明</text><text class="refund-rules-toggle">{{ refundRulesExpanded ? '收起' : '查看' }} ›</text></view><view v-if="refundRulesExpanded"><text class="refund-rules-item">仅已支付订单可在订单对应退款期限内申请；具体期限以订单页面显示为准。</text><text class="refund-rules-item">申请将进入后台审核。审核期间，该订单增加的名额会暂时冻结。</text><text class="refund-rules-item">若退款后现有成员会超过可用名额，或退款次数已用完，则不能继续申请。</text><text class="refund-rules-item">首次申请无需说明；再次申请请填写原因。每笔订单最多可申请 3 次。</text></view></view>
    <view v-if="loadingMore && !orders.length" class="orders-state archive-form-panel"><MiniEmptyState symbol="…" title="正在加载" description="正在同步扩容订单..." /></view>
    <view v-else-if="loadError && !orders.length" class="orders-state archive-form-panel"><MiniNotice tone="warm" title="加载失败">{{ loadError }}</MiniNotice><MiniButton variant="secondary" size="sm" @click="load">重新加载</MiniButton></view>
    <view v-else-if="orders.length" class="orders-section">
      <view class="orders-section-head"><text class="orders-title">订单记录</text><text class="orders-count">共 {{ filteredOrders.length }} / {{ totalOrders }} 笔</text></view>
      <scroll-view scroll-x class="order-tabs" :show-scrollbar="false"><view v-for="tab in statusTabs" :key="tab.value" class="order-tab" :class="{ active: statusFilter === tab.value, disabled: loadingMore }" @tap="selectStatus(tab.value)"><text>{{ tab.label }}</text></view></scroll-view>
      <view class="order-filter-row"><text class="filter-label">时间范围</text><picker mode="selector" :range="timeOptions" :value="timeIndex" :disabled="loadingMore" @change="onTimeChange"><view class="time-picker" :class="{ disabled: loadingMore }">{{ timeOptions[timeIndex] }} <text>⌄</text></view></picker></view>
      <view v-for="order in filteredOrders" :id="`capacity-order-${order.orderNo}`" :key="order.orderNo" class="order-card" :class="{ focused: order.orderNo === focusedOrderNo }">
        <view class="order-card-head"><text class="order-name">{{ order.productName }}</text><text class="order-status" :class="`status-${order.status.toLowerCase()}`">{{ orderStatusLabel(order.status) }}</text></view>
        <text class="order-meta">增加 {{ order.addedMembers }} 位可添加成员 · 支付 {{ (order.amountFen / 100).toFixed(2) }} 元</text>
        <text v-if="order.createdAt" class="order-time">下单时间 {{ formatOrderTime(order.createdAt) }}</text>
        <text v-if="order.status === 'PENDING' && order.expiresAt" class="order-time">超过 {{ formatOrderTime(order.expiresAt) }} 未支付将自动取消</text>
        <text v-if="order.status === 'PAID' && order.refundableUntil" class="order-time">可申请至 {{ formatOrderTime(order.refundableUntil) }} · 还可申请 {{ order.refundAttemptsRemaining ?? 3 }} 次</text>
        <text v-if="order.status === 'REFUNDING'" class="order-time refund-review-note">退款正在审核，扩容额度已冻结，审核结果会通知你。</text>
        <text v-if="order.lastRefundStatus === 'REJECTED' && order.lastRefundReason" class="order-time refund-rejected-note">上次未通过：{{ order.lastRefundReason }}</text>
        <view class="order-actions"><view v-if="canResumePayment(order)" class="reconcile-action" :class="{ disabled: orderActionBusy }" @tap="resumePayment(order)"><text>{{ payingOrderNo === order.orderNo ? '调起支付中' : '继续支付' }}</text></view><view v-if="canReconcile(order)" class="reconcile-action" :class="{ disabled: orderActionBusy }" @tap="reconcilePayment(order)"><text>{{ reconcilingOrderNo === order.orderNo ? '查询中' : '查询支付结果' }}</text></view><view v-if="isRefundAvailable(order)" class="refund-action" :class="{ disabled: orderActionBusy }" @tap="refund(order)"><text>{{ refundingOrderNo === order.orderNo ? '处理中' : '申请退款' }}</text></view><text v-else-if="order.status === 'PAID' && order.refundAttemptsRemaining === 0" class="refund-expired">退款申请已结束</text><text v-else-if="order.status === 'PAID' && order.refundableUntil" class="refund-expired">退款期限已过</text><text v-else-if="order.status === 'PAID'" class="refund-expired">退款资格同步中，请刷新订单</text></view>
        <view v-if="refundReasonOrderNo === order.orderNo" class="refund-reason-panel"><textarea v-model="refundReason" class="refund-reason-input" maxlength="500" placeholder="再次申请请填写退款理由" /><view class="refund-reason-actions"><view class="refund-cancel" :class="{ disabled: orderActionBusy }" @tap="cancelRefundReason">取消</view><view class="refund-confirm" :class="{ disabled: orderActionBusy }" @tap="submitRefund(order)">提交申请</view></view></view>
      </view>
      <view v-if="hasMore" class="more-orders" @tap="loadMore">{{ loadingMore ? '加载中…' : '加载更多订单' }}</view>
      <MiniNotice v-if="!filteredOrders.length" tone="warm">当前筛选范围暂无订单。</MiniNotice>
    </view>
    <MiniNotice v-else tone="warm">当前暂无扩容订单。</MiniNotice>
  </view>
</template>

<script setup lang="ts">
import { onLoad, onShow } from '@dcloudio/uni-app'
import { computed, ref, watch } from 'vue'
import { apiErrorMessage } from '@/api/client'
import { CapacityPaymentPendingError, listCapacityOrdersPage, reconcileCapacityPayment, requestCapacityRefund, resumeCapacityOrderPayment, type CapacityOrder } from '@/api/capacity'
import MiniBackHome from '@/components/base/MiniBackHome.vue'
import MiniButton from '@/components/base/MiniButton.vue'
import MiniEmptyState from '@/components/base/MiniEmptyState.vue'
import MiniNotice from '@/components/base/MiniNotice.vue'
import { requestSubscribeMessage } from '@/features/notifications/subscribe'

const familyId = ref(''); const returnTo = ref(''); const focusedOrderNo = ref(''); const orders = ref<CapacityOrder[]>([]); const totalOrders = ref(0); const currentPage = ref(1); const hasMore = ref(false); const loadingMore = ref(false); const loadError = ref(''); const refundingOrderNo = ref(''); const reconcilingOrderNo = ref(''); const payingOrderNo = ref(''); const refundReasonOrderNo = ref(''); const refundReason = ref(''); const refundRulesExpanded = ref(false); const statusFilter = ref('ALL'); const timeIndex = ref(0)
const returnUrl = computed(() => returnTo.value === 'tree' ? `/pages/family/private-tree?familyId=${encodeURIComponent(familyId.value)}` : `/pages/family/capacity?familyId=${encodeURIComponent(familyId.value)}`)
const returnLabel = computed(() => returnTo.value === 'tree' ? '返回家庭树' : '返回成员名额')
const statusTabs = [{ value: 'ALL', label: '全部' }, { value: 'PENDING', label: '待支付' }, { value: 'PAID', label: '已支付' }, { value: 'REFUNDING', label: '退款审核中' }, { value: 'REFUNDED', label: '已退款' }, { value: 'CANCELLED', label: '已取消' }]
const timeOptions = ['全部时间', '近 7 天', '近 30 天']; const timeDays = [0, 7, 30]
let skipInitialShow = true
const filteredOrders = computed(() => orders.value)
const orderActionBusy = computed(() => Boolean(refundingOrderNo.value || reconcilingOrderNo.value || payingOrderNo.value))
function isRefundAvailable(order: CapacityOrder) { return order.status === 'PAID' && Boolean(order.refundableUntil && Date.parse(order.refundableUntil) > Date.now()) && (order.refundAttemptsRemaining ?? 3) > 0 }
function canReconcile(order: CapacityOrder) { return order.status === 'PENDING' || order.status === 'CANCELLED' }
function canResumePayment(order: CapacityOrder) { return order.status === 'PENDING' && (!order.expiresAt || Date.parse(order.expiresAt) > Date.now()) }
function formatOrderTime(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString('zh-CN', { hour12: false }) }
function filterStartDate() { const days = timeDays[timeIndex.value]; if (!days) return undefined; const date = new Date(Date.now() - days * 86400000); const pad = (value: number) => String(value).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` }
async function load(reset = true): Promise<boolean> { if (loadingMore.value) return false; if (reset) { currentPage.value = 1; orders.value = []; totalOrders.value = 0 } loadingMore.value = true; loadError.value = ''; try { const result = await listCapacityOrdersPage(familyId.value, currentPage.value, 20, { status: statusFilter.value, startDate: filterStartDate() }); orders.value = [...orders.value, ...result.items].sort((a, b) => Date.parse(b.createdAt || '') - Date.parse(a.createdAt || '')); totalOrders.value = result.total; hasMore.value = orders.value.length < result.total; if (focusedOrderNo.value && orders.value.some((order) => order.orderNo === focusedOrderNo.value)) { statusFilter.value = 'ALL'; setTimeout(() => uni.pageScrollTo({ selector: `#capacity-order-${focusedOrderNo.value}`, duration: 220 }), 0) } return true } catch (error) { loadError.value = apiErrorMessage(error, '订单加载失败。'); return false } finally { loadingMore.value = false } }
async function loadMore() { if (!hasMore.value || loadingMore.value) return; const previousPage = currentPage.value; currentPage.value += 1; if (!await load(false)) currentPage.value = previousPage }
async function reconcilePayment(order: CapacityOrder) { if (orderActionBusy.value || !canReconcile(order)) return; reconcilingOrderNo.value = order.orderNo; try { const result = await reconcileCapacityPayment(familyId.value, order.orderNo); if (result.status === 'PAID') { uni.showToast({ title: '已确认支付成功，名额已到账', icon: 'none' }); await load() } else if (result.status === 'NOTPAY' || result.status === 'NOT_FOUND') { uni.showToast({ title: '微信暂未确认支付成功', icon: 'none' }) } else { uni.showToast({ title: `微信支付状态：${result.status}`, icon: 'none' }); await load() } } catch (error) { uni.showToast({ title: apiErrorMessage(error, '支付结果查询失败'), icon: 'none' }) } finally { reconcilingOrderNo.value = '' } }
async function resumePayment(order: CapacityOrder) { if (orderActionBusy.value || !canResumePayment(order)) return; payingOrderNo.value = order.orderNo; try { const latest = await resumeCapacityOrderPayment(familyId.value, order.orderNo); uni.showToast({ title: latest.status === 'PAID' ? '支付成功，名额已到账' : '支付结果待确认，请查询订单', icon: 'none' }); await load() } catch (error) { if (error instanceof CapacityPaymentPendingError) { uni.showToast({ title: error.message, icon: 'none' }); await load(); return }; uni.showToast({ title: apiErrorMessage(error, '暂时无法继续支付'), icon: 'none' }) } finally { payingOrderNo.value = '' } }
function selectStatus(status: string) { if (!loadingMore.value) statusFilter.value = status }
function onTimeChange(event: { detail: { value: number } }) { if (loadingMore.value) return; timeIndex.value = Number(event.detail.value); void load() }
function refund(order: CapacityOrder) { if (orderActionBusy.value || !isRefundAvailable(order)) return; if ((order.refundAttemptCount ?? 0) > 0) { refundReasonOrderNo.value = order.orderNo; refundReason.value = ''; return }; void submitRefund(order) }
function cancelRefundReason() { if (orderActionBusy.value) return; refundReasonOrderNo.value = ''; refundReason.value = '' }
async function submitRefund(order: CapacityOrder) { if (orderActionBusy.value || !isRefundAvailable(order)) return; refundingOrderNo.value = order.orderNo; try { await requestSubscribeMessage('refund'); await requestCapacityRefund(familyId.value, order.orderNo, refundReason.value.trim()); cancelRefundReason(); await load(); uni.showToast({ title: '退款申请已提交，等待后台审核', icon: 'none' }) } catch (error) { uni.showToast({ title: apiErrorMessage(error, '暂时无法退款'), icon: 'none' }) } finally { refundingOrderNo.value = '' } }
function orderStatusLabel(status: string) { return ({ PENDING: '待支付', PAID: '已支付', REFUNDING: '退款审核中', REFUNDED: '已退款', CANCELLED: '已取消' } as Record<string, string>)[status] || status }
watch(statusFilter, () => { void load() })
onLoad((options) => { familyId.value = String(options?.familyId || ''); returnTo.value = String(options?.returnTo || ''); focusedOrderNo.value = String(options?.orderNo || ''); if (focusedOrderNo.value) statusFilter.value = 'ALL'; void load() }); onShow(() => { if (skipInitialShow) { skipInitialShow = false; return }; if (familyId.value) void load() })
</script>

<style scoped>
.orders-page { padding-top: 28rpx; }.orders-state{margin-top:24rpx}.orders-state :deep(.mini-notice){margin-bottom:18rpx}.refund-rules{margin-top:22rpx;padding:22rpx;background:var(--archive-paper-deep);border:1px solid var(--archive-line);border-radius:14rpx}.refund-rules-head{display:flex;align-items:center;justify-content:space-between}.refund-rules-title,.refund-rules-item{display:block}.refund-rules-title{color:var(--archive-ink);font-size:27rpx;font-weight:700}.refund-rules-toggle{color:var(--archive-cinnabar);font-size:23rpx}.refund-rules-item{position:relative;margin-top:10rpx;padding-left:18rpx;color:var(--archive-ink-soft);font-size:22rpx;line-height:1.55}.refund-rules-item::before{content:'·';position:absolute;left:0;color:var(--archive-cinnabar)}.orders-section { margin-top: 28rpx; }.orders-section-head { display:flex; align-items:baseline; justify-content:space-between; margin-bottom:14rpx; }.orders-title { color:var(--archive-ink); font-size:29rpx; font-weight:700; }.orders-count { color:var(--archive-ink-soft); font-size:23rpx; }.order-tabs { white-space:nowrap; margin:0 -4rpx 12rpx; }.order-tab { display:inline-flex; align-items:center; justify-content:center; min-width:104rpx; padding:12rpx 18rpx; margin-right:10rpx; border:1px solid var(--archive-line); border-radius:999rpx; color:var(--archive-ink-soft); font-size:23rpx; }.order-tab.active { color:var(--archive-cinnabar); border-color:var(--archive-cinnabar); background:var(--archive-paper); }.order-tab.disabled,.time-picker.disabled { opacity:.55; }.order-filter-row { display:flex; align-items:center; justify-content:space-between; margin-bottom:12rpx; color:var(--archive-ink-soft); font-size:23rpx; }.time-picker { padding:10rpx 16rpx; border:1px solid var(--archive-line); border-radius:10rpx; color:var(--archive-ink); background:var(--archive-paper); }.time-picker text { margin-left:10rpx; color:var(--archive-cinnabar); }.order-card { margin-bottom:14rpx; padding:24rpx; background:var(--archive-paper-deep); border:1px solid var(--archive-line); border-radius:14rpx; }.order-card.focused { border-color:rgba(168,59,45,.55); box-shadow:0 0 0 4rpx rgba(168,59,45,.07); }.order-card-head { display:flex; align-items:center; justify-content:space-between; gap:16rpx; }.order-name { color:var(--archive-ink); font-size:27rpx; font-weight:700; }.order-status { flex:0 0 auto; font-size:23rpx; }.status-paid { color:var(--archive-green,#2f6b57); }.status-refunding { color:var(--archive-cinnabar); }.status-refunded,.status-pending,.status-cancelled { color:var(--archive-ink-soft); }.order-meta,.order-time { display:block; margin-top:8rpx; color:var(--archive-ink-soft); font-size:23rpx; line-height:1.5; }.refund-review-note { color:var(--archive-cinnabar); }.refund-rejected-note { color:var(--archive-cinnabar); }.order-actions { display:flex; justify-content:flex-end; gap:14rpx; margin-top:14rpx; }.refund-action,.reconcile-action { padding:12rpx 18rpx; border-radius:10rpx; font-size:24rpx; }.refund-action { color:var(--archive-cinnabar); border:1px solid var(--archive-cinnabar); }.reconcile-action { color:var(--archive-ink); border:1px solid var(--archive-line-strong); }.refund-action:active,.reconcile-action:active { opacity:.72; }.refund-action.disabled,.reconcile-action.disabled { opacity:.55; }.refund-expired { color:var(--archive-ink-soft); font-size:23rpx; }.refund-reason-panel { margin-top:16rpx; padding-top:16rpx; border-top:1px solid var(--archive-line); }.refund-reason-input { width:100%; min-height:120rpx; box-sizing:border-box; padding:16rpx; background:var(--archive-paper); border:1px solid var(--archive-line); border-radius:10rpx; color:var(--archive-ink); font-size:24rpx; }.refund-reason-actions { display:flex; justify-content:flex-end; gap:16rpx; margin-top:12rpx; }.refund-cancel,.refund-confirm { padding:12rpx 18rpx; border-radius:10rpx; font-size:24rpx; }.refund-cancel { color:var(--archive-ink-soft); border:1px solid var(--archive-line); }.refund-confirm { color:var(--archive-paper); background:var(--archive-cinnabar); }.more-orders { margin:22rpx 0 8rpx;color:var(--archive-blue);font-size:24rpx;text-align:center; }
.refund-cancel.disabled,.refund-confirm.disabled { opacity:.55; }
</style>
